REQUESTDATA.TALLYMESSAGE:
{% for record in records %}
{% assign voucher = record.voucher_data %}

  {{ voucher.date | date: '%Y%m%d' }}

    {% if voucher.referencedate %}
    {{ voucher.referencedate | date: '%Y%m%d' }}
    {% else %}
    {{ voucher.date | date: '%Y%m%d' }}
    {% endif %}

  {{ voucher.state }}
  {{ voucher.narration }}
  {{ voucher.country }}
  {{ voucher.reference }}
  {{ voucher.voucher_number }}
  {{ voucher.gstin }}
  {{ voucher.gl_name }}
  {{ voucher.voucher_type }}
  {{ voucher.gl_name }}
  {{ voucher.gl_name }}

    {% if voucher.effective_date %}
    {{ voucher.effective_date | date: '%Y%m%d' }}
    {% else %}
    {{ voucher.date | date: '%Y%m%d' }}
    {% endif %}

  {% for ledger in voucher.ledgers %}

      {{ ledger.name }}
      {{ ledger.isdeemedpositive }}
      {{ ledger.ISPARTYLEDGER }}
      {{ ledger.AMOUNT }}

      {% for billallocation in ledger.billallocations %}

          {{ billallocation.name }}
          {{ billallocation.type }}
          {{ billallocation.amount }}

      {% endfor %}

      {% for categoryallocation in ledger.categoryallocations %}

          {{ categoryallocation.name }}
          Yes
          {% for costcenter in categoryallocation.costcenters %}

              {{ costcenter.name }}
              {{ costcenter.amount }}

          {% endfor %}

      {% endfor %}

      {% for bankallocation in ledger.bankallocations %}

          {{ bankallocation.name }}
          {{ bankallocation.date | date: '%Y%m%d' }}

            {% if bankallocation.instrument_date %}
            {{ bankallocation.instrument_date | date: '%Y%m%d' }}
            {% else %}
            {{ bankallocation.date | date: '%Y%m%d' }}
            {% endif %}

          {{ bankallocation.utr }}
          {{ bankallocation.utr }}
          {{ bankallocation.transaction_type }}
          {{ bankallocation.payment_mode }}
          {{ bankallocation.party_name }}
          {{ bankallocation.amount }}

      {% endfor %}

  {% endfor %}

{% endfor %}
